declare(strict_types=1); require_once __DIR__.DIRECTORY_SEPARATOR.'auth.php'; admin_require_login(); send_security_headers(true);$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id){http_response_code(400);exit;}$q=db_connection()->prepare("SELECT stored_filename,mime_type FROM photos WHERE id=? AND visibility='public' LIMIT 1");$q->execute([$id]);$x=$q->fetch();if(!is_array($x)){http_response_code(404);exit;}$path=gallery_resolve_file((string)app_config('UPLOAD_STORAGE_PATH'),(string)$x['stored_filename']);if($path===null||gallery_detect_mime($path)!==(string)$x['mime_type']){http_response_code(404);exit;}header('Content-Type: '.$x['mime_type']);header('X-Content-Type-Options: nosniff');header('Content-Length: '.(string)filesize($path));header('Cache-Control: no-store');readfile($path);
